import { useState, useEffect } from 'react';
import { Save, RefreshCw, CheckCircle, Plus, X } from 'lucide-react';
import { PageHeader } from '../components/PageHeader';
import { api, type PlatformSettings } from '../lib/api';

// ── Building blocks ────────────────────────────────────────────────────────────

function SectionCard({ title, subtitle, children }: { title: string; subtitle?: string; children: React.ReactNode }) {
  return (
    <div className="bg-white rounded-xl border border-gray-200 p-5 mb-5">
      <div className="mb-4">
        <h3 className="text-sm font-semibold text-gray-900">{title}</h3>
        {subtitle && <p className="text-xs text-gray-500 mt-0.5">{subtitle}</p>}
      </div>
      {children}
    </div>
  );
}

function Toggle({
  label,
  description,
  value,
  onChange,
}: {
  label: string;
  description: string;
  value: boolean;
  onChange: (v: boolean) => void;
}) {
  return (
    <div className="flex items-center justify-between py-3.5 border-b border-gray-100 last:border-0 gap-4">
      <div className="min-w-0">
        <p className="text-sm font-medium text-gray-800">{label}</p>
        <p className="text-xs text-gray-500 mt-0.5 leading-relaxed">{description}</p>
      </div>
      <button
        onClick={() => onChange(!value)}
        className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors flex-shrink-0 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-1 ${
          value ? 'bg-indigo-600' : 'bg-gray-200'
        }`}
        aria-checked={value}
        role="switch"
      >
        <span
          className={`inline-block h-4 w-4 transform rounded-full bg-white shadow transition-transform ${
            value ? 'translate-x-6' : 'translate-x-1'
          }`}
        />
      </button>
    </div>
  );
}

function InputField({
  label,
  settingKey,
  type = 'text',
  settings,
  onChange,
}: {
  label: string;
  settingKey: string;
  type?: string;
  settings: PlatformSettings;
  onChange: (key: string, value: string) => void;
}) {
  return (
    <div className="mb-4">
      <label className="block text-xs font-medium text-gray-600 mb-1.5">{label}</label>
      <input
        type={type}
        value={String(settings[settingKey] ?? '')}
        onChange={(e) => onChange(settingKey, e.target.value)}
        className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition"
      />
    </div>
  );
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function EmailListField({
  label,
  description,
  settingKey,
  settings,
  onChange,
}: {
  label: string;
  description: string;
  settingKey: string;
  settings: PlatformSettings;
  onChange: (key: string, value: string[]) => void;
}) {
  const raw = settings[settingKey];
  const emails = Array.isArray(raw) ? raw as string[] : [];
  const [draft, setDraft]   = useState('');
  const [error, setError]   = useState<string | null>(null);

  function addEmail() {
    const cleaned = draft.trim().toLowerCase();
    if (!cleaned) return;
    if (!EMAIL_RE.test(cleaned)) { setError('Enter a valid email address'); return; }
    if (emails.includes(cleaned)) { setError('That email is already on the list'); return; }
    onChange(settingKey, [...emails, cleaned]);
    setDraft('');
    setError(null);
  }

  function removeEmail(email: string) {
    onChange(settingKey, emails.filter((e) => e !== email));
  }

  return (
    <div className="mb-2">
      <label className="block text-xs font-medium text-gray-600 mb-1.5">{label}</label>
      <p className="text-xs text-gray-500 mb-2 leading-relaxed">{description}</p>

      <div className="flex gap-2 mb-2">
        <input
          type="email"
          value={draft}
          onChange={(e) => { setDraft(e.target.value); setError(null); }}
          onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); addEmail(); } }}
          placeholder="brand@example.com"
          className="flex-1 px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition"
        />
        <button
          type="button"
          onClick={addEmail}
          className="flex items-center gap-1.5 px-3 py-2 text-sm font-medium text-indigo-600 border border-indigo-200 rounded-lg hover:bg-indigo-50 transition-colors"
        >
          <Plus size={14} />
          Add
        </button>
      </div>
      {error && <p className="text-xs text-red-600 mb-2">{error}</p>}

      {emails.length > 0 ? (
        <div className="flex flex-wrap gap-2">
          {emails.map((email) => (
            <span
              key={email}
              className="inline-flex items-center gap-1.5 pl-2.5 pr-1.5 py-1 text-xs font-medium text-indigo-700 bg-indigo-50 border border-indigo-100 rounded-full"
            >
              {email}
              <button
                type="button"
                onClick={() => removeEmail(email)}
                className="p-0.5 rounded-full hover:bg-indigo-100 transition-colors"
                aria-label={`Remove ${email}`}
              >
                <X size={11} />
              </button>
            </span>
          ))}
        </div>
      ) : (
        <p className="text-xs text-gray-400">No businesses on the allowlist yet.</p>
      )}
    </div>
  );
}

// ── Default settings ───────────────────────────────────────────────────────────

const DEFAULTS: PlatformSettings = {
  'platform.comingSoon':         false,
  'business.registrationEnabled': true,
  'creator.registrationEnabled':  true,
  'creator.onboarding':          true,
  'business.onboarding':         true,
  'campaign.autoApproval':       true,
  'payment.escrow':              true,
  'messaging.enabled':           true,
  'messaging.directMessages':    true,
  'messaging.pushNotifications': true,
  'messaging.typingIndicators':  true,
  'notifications.email':         true,
  'notifications.reportAlerts':  true,
  'notifications.paymentAlerts': true,
  'notifications.weeklySummary': false,
  'security.twoFactor':          true,
  'security.ipAllowlist':        false,
  'security.auditLogging':       true,
  'security.sessionTimeout':     true,
  'platform.name':               'Kolab',
  'platform.supportEmail':       'support@collab.com',
  'platform.commission':         '12',
  'platform.paymentFeePercent':  '5',
  'platform.paymentTaxPercent':  '13',
  'platform.description':        'Kolab connects brands with top creators for authentic events.',
  'marketplace.launchPriorityCity': 'Itahari',
  'featuredEvent.paywallEnabled': false,
  'featuredEvent.freeQuota':      3,
  'featuredEvent.price':          1000,
  'featuredEvent.unlimitedEmails': [] as string[],
  'app.minVersion.ios':           '',
  'app.minVersion.android':       '',
};

// ── Main component ─────────────────────────────────────────────────────────────

export function Settings() {
  const [settings,  setSettings]  = useState<PlatformSettings>(DEFAULTS);
  const [loading,   setLoading]   = useState(true);
  const [saving,    setSaving]    = useState(false);
  const [saved,     setSaved]     = useState(false);
  const [error,     setError]     = useState<string | null>(null);

  useEffect(() => {
    loadSettings();
  }, []);

  async function loadSettings() {
    setLoading(true);
    setError(null);
    try {
      const res = await api.admin.getSettings();
      setSettings({ ...DEFAULTS, ...res.data });
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setLoading(false);
    }
  }

  function toggle(key: string, value: boolean) {
    setSettings((prev) => ({ ...prev, [key]: value }));
  }

  function setString(key: string, value: string) {
    setSettings((prev) => ({ ...prev, [key]: value }));
  }

  function setArray(key: string, value: string[]) {
    setSettings((prev) => ({ ...prev, [key]: value }));
  }

  async function handleSave() {
    setSaving(true);
    setError(null);
    try {
      const res = await api.admin.updateSettings(settings);
      setSettings({ ...DEFAULTS, ...res.data });
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setSaving(false);
    }
  }

  const bool = (key: string) => Boolean(settings[key] ?? DEFAULTS[key] ?? false);

  if (loading) {
    return (
      <div>
        <PageHeader title="Settings" />
        <div className="max-w-2xl space-y-5">
          {[1, 2, 3, 4].map((i) => (
            <div key={i} className="bg-white rounded-xl border border-gray-200 p-5 animate-pulse">
              <div className="h-4 bg-gray-200 rounded w-1/3 mb-4" />
              {[1, 2, 3].map((j) => <div key={j} className="h-10 bg-gray-100 rounded mb-2" />)}
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div>
      <PageHeader
        title="Settings"
        subtitle="Configure platform-wide features and controls"
        action={
          <div className="flex items-center gap-3">
            {saved && (
              <span className="flex items-center gap-1.5 text-sm text-emerald-600 font-medium">
                <CheckCircle size={15} />
                Saved
              </span>
            )}
            <button
              onClick={loadSettings}
              className="flex items-center gap-2 px-3 py-2 text-sm text-gray-600 border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors"
            >
              <RefreshCw size={14} />
              Reload
            </button>
            <button
              onClick={handleSave}
              disabled={saving}
              className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-700 disabled:opacity-60 transition-colors"
            >
              <Save size={15} />
              {saving ? 'Saving…' : 'Save Changes'}
            </button>
          </div>
        }
      />

      {error && (
        <div className="mb-5 p-4 bg-red-50 border border-red-200 rounded-xl text-sm text-red-700 max-w-2xl">
          {error}
        </div>
      )}

      <div className="max-w-2xl">

        {/* Platform */}
        <SectionCard title="Platform Settings" subtitle="Core controls for registration and onboarding">
          <Toggle label="Coming Soon Mode"      description="Hide the App Store / Google Play download buttons on the public landing page and show a Coming Soon badge instead" value={bool('platform.comingSoon')} onChange={(v) => toggle('platform.comingSoon', v)} />
          <Toggle label="Business Registration" description="Allow new businesses to sign up on the platform"                  value={bool('business.registrationEnabled')} onChange={(v) => toggle('business.registrationEnabled', v)} />
          <Toggle label="Creator Registration"  description="Allow new creators to sign up on the platform"                   value={bool('creator.registrationEnabled')}  onChange={(v) => toggle('creator.registrationEnabled', v)} />
          <Toggle label="Creator Onboarding"    description="Enable the creator onboarding flow for new users"                value={bool('creator.onboarding')}    onChange={(v) => toggle('creator.onboarding', v)} />
          <Toggle label="Business Onboarding"   description="Enable the business onboarding flow for new users"               value={bool('business.onboarding')}   onChange={(v) => toggle('business.onboarding', v)} />
          <Toggle label="Event Auto-Approval"    description="When off, new events go into a pending-review queue and stay hidden from creators until an admin approves them" value={bool('campaign.autoApproval')} onChange={(v) => toggle('campaign.autoApproval', v)} />
          <Toggle label="Payment Escrow"         description="Hold payments in escrow until event completion is confirmed"      value={bool('payment.escrow')}        onChange={(v) => toggle('payment.escrow', v)} />
        </SectionCard>

        {/* Messaging */}
        <SectionCard title="Messaging & Chat" subtitle="Control the real-time chat system between creators and businesses">
          <Toggle
            label="Messaging Enabled"
            description="Master switch — turns off the entire chat/messaging feature across the app"
            value={bool('messaging.enabled')}
            onChange={(v) => toggle('messaging.enabled', v)}
          />
          <Toggle
            label="Direct Messages"
            description="Allow creators to initiate conversations with businesses (not just receive requests)"
            value={bool('messaging.directMessages')}
            onChange={(v) => toggle('messaging.directMessages', v)}
          />
          <Toggle
            label="Push Notifications"
            description="Send mobile push notifications when a new message is received"
            value={bool('messaging.pushNotifications')}
            onChange={(v) => toggle('messaging.pushNotifications', v)}
          />
          <Toggle
            label="Typing Indicators"
            description="Show the animated '…' typing indicator when the other party is composing"
            value={bool('messaging.typingIndicators')}
            onChange={(v) => toggle('messaging.typingIndicators', v)}
          />
        </SectionCard>

        {/* Notifications */}
        <SectionCard title="Notification Settings" subtitle="Control which alerts are sent to admins and users">
          <Toggle label="Email Notifications"   description="Send email alerts for reports and user flags"                          value={bool('notifications.email')}         onChange={(v) => toggle('notifications.email', v)} />
          <Toggle label="New Report Alerts"     description="Notify admins immediately when a new report is filed"                  value={bool('notifications.reportAlerts')}  onChange={(v) => toggle('notifications.reportAlerts', v)} />
          <Toggle label="Payment Failure Alerts" description="Alert the admin team when a payment fails to process"                  value={bool('notifications.paymentAlerts')} onChange={(v) => toggle('notifications.paymentAlerts', v)} />
          <Toggle label="Weekly Summary Email"  description="Send a weekly digest of platform activity to admins"                   value={bool('notifications.weeklySummary')} onChange={(v) => toggle('notifications.weeklySummary', v)} />
        </SectionCard>

        {/* Platform Info */}
        <SectionCard title="Platform Information" subtitle="Brand details shown across the app">
          <InputField label="Platform Name"            settingKey="platform.name"          settings={settings} onChange={setString} />
          <InputField label="Support Email"            settingKey="platform.supportEmail"  settings={settings} onChange={setString} type="email" />
          <InputField label="Platform Commission (%)"  settingKey="platform.commission"    settings={settings} onChange={setString} type="number" />
          <div className="mb-4">
            <label className="block text-xs font-medium text-gray-600 mb-1.5">Platform Description</label>
            <textarea
              rows={3}
              value={String(settings['platform.description'] ?? '')}
              onChange={(e) => setString('platform.description', e.target.value)}
              className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition resize-none"
            />
          </div>
        </SectionCard>

        {/* Payment Fees */}
        <SectionCard title="Payment Fees" subtitle="Platform fee and tax added to the total when a business pays a creator — shown live in the mobile app's Complete Payment screen">
          <InputField label="Platform Fee (%)" settingKey="platform.paymentFeePercent" settings={settings} onChange={setString} type="number" />
          <InputField label="Tax (%)"          settingKey="platform.paymentTaxPercent" settings={settings} onChange={setString} type="number" />
        </SectionCard>

        {/* Marketplace */}
        <SectionCard title="Marketplace" subtitle="Controls which market the marketplace currently favors — change this as the launch expands to new cities">
          <InputField label="Launch Priority City" settingKey="marketplace.launchPriorityCity" settings={settings} onChange={setString} />
          <p className="text-xs text-gray-400 -mt-2">
            Recommended providers ranking for businesses favors this city first, then falls back to distance/quality. Leave blank to disable city-priority entirely.
          </p>
        </SectionCard>

        {/* Featured Events */}
        <SectionCard title="Featured Events" subtitle="Control whether businesses pay to feature events, or feature them for free">
          <Toggle
            label="Featured Event Paywall"
            description="Off — every business can feature unlimited events for free. On — each business gets a limited number of free features, then must pay to feature more."
            value={bool('featuredEvent.paywallEnabled')}
            onChange={(v) => toggle('featuredEvent.paywallEnabled', v)}
          />

          {bool('featuredEvent.paywallEnabled') && (
            <div className="pt-4">
              <InputField label="Free featured events per business" settingKey="featuredEvent.freeQuota" settings={settings} onChange={setString} type="number" />
              <InputField label="Price to feature after the free quota (Rs.)" settingKey="featuredEvent.price" settings={settings} onChange={setString} type="number" />
              <p className="text-xs text-gray-400 -mt-2 mb-4">
                No charge is collected automatically yet — the price is shown to the business in the app as the amount they'd owe to feature beyond the free quota.
              </p>

              <EmailListField
                label="Allowlisted business emails"
                description="Businesses on this list always feature for free, even while the paywall is on. Must match the email the business signs in with. Case-insensitive."
                settingKey="featuredEvent.unlimitedEmails"
                settings={settings}
                onChange={setArray}
              />
            </div>
          )}
        </SectionCard>

        {/* App Version */}
        <SectionCard title="Minimum App Version" subtitle="Mobile installs older than these versions are blocked with an update screen. Leave blank to disable enforcement for that platform.">
          <InputField label="iOS Minimum Version"     settingKey="app.minVersion.ios"     settings={settings} onChange={setString} />
          <InputField label="Android Minimum Version" settingKey="app.minVersion.android" settings={settings} onChange={setString} />
        </SectionCard>

        {/* Security */}
        <SectionCard title="Security" subtitle="Access controls and audit settings for the admin panel">
          <Toggle label="Two-Factor Authentication" description="Require 2FA for all admin accounts"                        value={bool('security.twoFactor')}      onChange={(v) => toggle('security.twoFactor', v)} />
          <Toggle label="IP Allowlisting"           description="Restrict admin panel access to approved IP addresses only" value={bool('security.ipAllowlist')}    onChange={(v) => toggle('security.ipAllowlist', v)} />
          <Toggle label="Audit Logging"             description="Log all admin actions for compliance and accountability"   value={bool('security.auditLogging')}   onChange={(v) => toggle('security.auditLogging', v)} />
          <Toggle label="Session Timeout"           description="Automatically sign out inactive admin sessions after 30 min" value={bool('security.sessionTimeout')} onChange={(v) => toggle('security.sessionTimeout', v)} />
        </SectionCard>

      </div>
    </div>
  );
}
